const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const naivashaPoint = ee.Geometry.Point(36.4333, -0.7167);
    const geometry = naivashaPoint.buffer(20000); // 20 km buffer around Naivasha

    const date1_start = '1986-01-01';
    const date1_end = '1986-12-31';
    const date2_start = '2000-01-01';
    const date2_end = '2000-12-31';

    const scale = 1000; // Use a reasonable scale to avoid memory issues for region reduction
    const ndbiThreshold = 0; // A common threshold to delineate built-up areas (NDBI > 0 for built-up)

    // Function to mask clouds and shadows from Landsat 5 SR data
    function maskL5sr(image) {
      const qa = image.select('pixel_qa');
      // Bits 3 and 5 are cloud shadow and cloud, respectively.
      const cloudShadowBitMask = (1 << 3);
      const cloudsBitMask = (1 << 5);
      // Both flags should be set to zero, indicating clear conditions.
      const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
        .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
      return image.updateMask(mask).divide(10000)
        .select(['B5', 'B4']) // Select bands needed for NDBI (SWIR1, NIR)
        .copyProperties(image, ['system:time_start']);
    }

    // Function to calculate NDBI (Normalized Difference Built-up Index)
    function calculateNDBI(image) {
      // NDBI = (SWIR1 - NIR) / (SWIR1 + NIR)
      // Landsat 5: SWIR1 = B5, NIR = B4
      return image.normalizedDifference(['B5', 'B4']).rename('NDBI');
    }

    // Function to process image collection for a given period
    async function getNDBIImage(startDate, endDate, periodName) {
      let collection = ee.ImageCollection('LANDSAT/LT05/C01/T1_SR')
        .filterDate(startDate, endDate)
        .filterBounds(geometry);

      const initialSize = await collection.size().getInfo();
      if (initialSize === 0) {
        // Fallback: broaden date range to 2 years if no images found
        const fallbackStartDate = ee.Date(startDate).advance(-1, 'year').format('YYYY-MM-DD').getInfo();
        const fallbackEndDate = ee.Date(endDate).advance(1, 'year').format('YYYY-MM-DD').getInfo();
        console.log(`Warning: No images for ${periodName} (${startDate}-${endDate}). Trying broader range: ${fallbackStartDate}-${fallbackEndDate}`);
        collection = ee.ImageCollection('LANDSAT/LT05/C01/T1_SR')
          .filterDate(fallbackStartDate, fallbackEndDate)
          .filterBounds(geometry);
      }

      const finalSize = await collection.size().getInfo();
      if (finalSize === 0) {
        console.log(`Error: No images found for ${periodName} even after broadening date range.`);
        return { urbanArea: null, imageCount: 0, validPixels: 0 };
      }

      const maskedCollection = collection.map(maskL5sr);
      const ndbiCollection = maskedCollection.map(calculateNDBI);

      // Take the median composite to reduce noise and cloud effects
      const medianNDBI = ndbiCollection.median();

      if (!medianNDBI) {
        console.log(`Error: Could not create median NDBI image for ${periodName}.`);
        return { urbanArea: null, imageCount: finalSize, validPixels: 0 };
      }

      // Calculate valid pixels after masking and before NDBI thresholding
      const bandToCount = medianNDBI.bandNames().get(0).getInfo(); // Get the NDBI band name
      const validPixels = await medianNDBI.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geometry,
        scale: scale,
        maxPixels: 1e9
      }).get(bandToCount).getInfo();

      if (validPixels === 0 || validPixels === null) {
        console.log(`No valid pixels remaining for ${periodName} after cloud masking.`);
        return { urbanArea: null, imageCount: finalSize, validPixels: 0 };
      }

      // Classify urban areas based on NDBI threshold
      const urbanAreaImage = medianNDBI.gt(ndbiThreshold).selfMask();

      // Calculate the area of urban pixels
      const urbanAreaSqM = await urbanAreaImage.multiply(ee.Image.pixelArea())
        .reduceRegion({
          reducer: ee.Reducer.sum(),
          geometry: geometry,
          scale: scale,
          maxPixels: 1e9
        }).get('NDBI').getInfo(); // 'NDBI' is the band name after selfMask

      const urbanAreaSqKm = urbanAreaSqM !== null ? urbanAreaSqM / 1e6 : null;

      return { urbanArea: urbanAreaSqKm, imageCount: finalSize, validPixels: validPixels };
    }

    // 2. Data Acquisition & Check
    console.log('Processing 1986 data...');
    const result1986 = await getNDBIImage(date1_start, date1_end, '1986');
    const urbanArea1986 = result1986.urbanArea;
    const images1986 = result1986.imageCount;
    const pixels1986 = result1986.validPixels;

    console.log('Processing 2000 data...');
    const result2000 = await getNDBIImage(date2_start, date2_end, '2000');
    const urbanArea2000 = result2000.urbanArea;
    const images2000 = result2000.imageCount;
    const pixels2000 = result2000.validPixels;

    // 3. Validation & Final Answer
    if (images1986 === 0 || images2000 === 0) {
      console.log(`1986 Images: ${images1986}, 2000 Images: ${images2000}`);
      console.log('C1: Empty Collection (No images found in date/location for one or both comparison points).');
      return;
    }

    if (pixels1986 === 0 || pixels2000 === 0) {
      console.log(`1986 Images: ${images1986} (Valid Pixels: ${pixels1986}), 2000 Images: ${images2000} (Valid Pixels: ${pixels2000})`);
      console.log('C2: No Valid Pixels (Images exist, but after cloud masking/processing, 0 pixels remain).');
      return;
    }

    if (urbanArea1986 === null || urbanArea2000 === null || isNaN(urbanArea1986) || isNaN(urbanArea2000)) {
      console.log(`1986 Urban Area: ${urbanArea1986}, 2000 Urban Area: ${urbanArea2000}`);
      console.log('C3: Calculation Failure (Result is None, NaN, or invalid).');
      return;
    }

    console.log(`1986 Images: ${images1986} (Val Pixels: ${pixels1986})`);
    console.log(`2000 Images: ${images2000} (Val Pixels: ${pixels2000})`);
    console.log(`1986 Urban Area: ${urbanArea1986.toFixed(2)} sq km`);
    console.log(`2000 Urban Area: ${urbanArea2000.toFixed(2)} sq km`);

    if (urbanArea2000 > urbanArea1986) {
      console.log('A'); // Yes, urban area increased
    } else {
      console.log('B'); // No, urban area did not increase or stayed same/decreased
    }

  } catch (e) {
    console.log(`An error occurred: ${e.message}`);
    console.log('D'); // General error / Calculation failure
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
